\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:3;a:5:{s:4:\"data\";s:11:\"development\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:4;a:5:{s:4:\"data\";s:8:\"releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=22114\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:361:\"Release Candidate 3 (“RC3”) for WordPress 7.2 is ready for download and testing! This version of the WordPress software is still under development. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, it’s recommended to evaluate RC3 on a test server and site. Wait, what happened to [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"David Baumwald\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:8416:\"\n<p class=\"wp-block-paragraph\">Release Candidate 3 (“RC3”) for WordPress 7.2 is ready for download and testing!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>This version of the WordPress software is still under development</strong>. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, it’s recommended to evaluate RC3 on a test server and site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Wait, what happened to 7.2 RC2? Changes in <a href=\"https://wordpress.org/news/2026/11/wordpress-7-1-5-release/\">WordPress 7.1.5</a> were simultaneously applied to WordPress 7.2 RC2.</p>\n\n\n\n<h2 class=\"wp-block-heading\">WordPress testing methods</h2>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>Plugin</strong></td><td>Install and activate the <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\" rel=\"noopener\" target=\"_blank\">WordPress Beta Tester</a> plugin on a WordPress install. Select the “Bleeding edge” channel and “Beta/RC Only” stream.</td></tr><tr><td><strong>Direct Download</strong></td><td>Download the <a href=\"https://wordpress.org/wordpress-7.2-RC3.zip\">RC3 version (zip)</a> and install it on a WordPress website.</td></tr><tr><td><strong>Command Line</strong></td><td>Use this <a href=\"https://make.wordpress.org/cli/\">WP-CLI</a> command: <br><code>wp core update --version=7.2-RC3</code></td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use the <a href=\"http://playground.wordpress.net/release\" rel=\"noopener\" target=\"_blank\">WordPress Playground instance</a> to test the software directly in your browser. No setup required – just click and go!</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The scheduled release date for WordPress 7.2 is <strong>December 8, 2026</strong>. The full <a href=\"https://make.wordpress.org/core/2026/10/06/wordpress-7-2-release-party-schedule/\" rel=\"noopener\" target=\"_blank\">release schedule can be found here</a>. Your help testing Beta and RC versions is vital to making this release as stable and powerful as possible. Thank you to everyone who contributes by testing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Please continue checking the <a href=\"https://make.wordpress.org/core/\" rel=\"noopener\" target=\"_blank\">Make WordPress Core blog</a> for <a href=\"https://make.wordpress.org/core/tag/7-2\" rel=\"noopener\" target=\"_blank\">7.2-related posts</a> in the coming weeks for more information.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Core changes since RC1</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Check out the <a href=\"https://wordpress.org/news/2026/11/wordpress-7-2-release-candidate-1/\">RC1 announcement</a> for details on WordPress 7.2. You can browse the technical details for all issues addressed since RC1 using these links:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://core.trac.wordpress.org/query?changetime=11%2F17%2F2026..11%2F24%2F2026&amp;milestone=7.2&amp;status=closed&amp;group=component&amp;order=id&amp;col=id&amp;col=summary&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority\">Closed 7.2 WordPress Core Trac tickets</a> since November 17, 2026</li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/commits/wp/7.2?since=2026-11-17&amp;until=2026-11-24\">7.2 Gutenberg commits</a> since November 17, 2026</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">This release brings additional bug fixes, accessibility improvements, and compatibility updates: improved client-side media processing, fixes for navigation menus with outdated item counts, and more reliable handling of HTML and revision metadata. Additional changes strengthen email header handling, address font upload compatibility, and refine the performance of random-content redirects on larger sites.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/66769\">Trac #66769</a>, <a href=\"https://core.trac.wordpress.org/ticket/66668\">Trac #66668</a>, <a href=\"https://core.trac.wordpress.org/ticket/66102\">Trac #66102</a>, <a href=\"https://core.trac.wordpress.org/ticket/66490\">Trac #66490</a>, <a href=\"https://core.trac.wordpress.org/ticket/66654\">Trac #66654</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">Additional Block Editor improvements</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 RC3 includes further refinements to the Block Editor, with improvements to security, accessibility, and media handling. Recent fixes strengthen the handling of external image metadata and entity records, preserve filenames during media transformations, and improve consistency between client-side and server-side Interactivity API behavior. Additional updates simplify editor controls for non-hierarchical post types and improve accessibility labels.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/pull/87015\">GitHub #87015</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/87150\">GitHub #87150</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/87275\">GitHub #87275</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">How you can contribute</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress is open source software made possible by a passionate community of people collaborating on and contributing to its development. The resources below outline various ways you can help the world’s most popular open source web platform, regardless of your technical expertise.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Get involved in testing</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Your help testing the WordPress 7.2 RC3 version is key to ensuring that the final release is the best it can be. While testing the upgrade process is essential, trying out new features is equally important. This <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\" rel=\"noopener\" target=\"_blank\">detailed guide</a> will walk you through testing features in WordPress 7.2.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Curious about testing releases in general? Follow along with the <a href=\"https://make.wordpress.org/test/\" rel=\"noopener\" target=\"_blank\">testing initiatives in Make Core</a> and join the <a href=\"https://wordpress.slack.com/messages/core-test/\" rel=\"noopener\" target=\"_blank\">#core-test channel</a> on <a href=\"https://wordpress.slack.com/\" rel=\"noopener\" target=\"_blank\">Making WordPress Slack</a>.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Update your theme or plugin</h3>\n\n\n\n<p class=\"wp-block-paragraph\">For plugin and theme authors, your products play an integral role in extending the functionality and value of WordPress for all users. With RC3, you’ll want to conclude your testing and update the <em>“Tested up to”</em> version in your <a href=\"https://developer.wordpress.org/plugins/wordpress-org/how-your-readme-txt-works/\" rel=\"noopener\" target=\"_blank\">plugin’s readme file</a> to 7.2.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you find compatibility issues, please post detailed information to the <a href=\"https://wordpress.org/support/forum/alphabeta/\" rel=\"noopener\" target=\"_blank\">support forum</a>.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Test on your hosting platforms</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Thank you to all <a href=\"https://make.wordpress.org/hosting/test-results/\" rel=\"noopener\" target=\"_blank\">web hosts who help test WordPress</a>. Web hosts provide vital infrastructure for supporting WordPress and its users. Testing on hosting systems helps inform the development process while ensuring that WordPress and hosting platforms are fully compatible, free of errors, optimized for the best possible user experience, and that updates roll out to customer sites without issue.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Want to test WordPress on your hosting system? <a href=\"https://make.wordpress.org/hosting/test-results-getting-started/\" rel=\"noopener\" target=\"_blank\">Get started with configuring distributed hosting tests here</a>. </p>\n\n\n\n<h2 class=\"wp-block-heading\">An RC3 haiku</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><em>RC Three is here</em><br><em>The final touches take shape</em><br><em>Release day is near</em></p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Props to </em><a href=\'https://profiles.wordpress.org/audrasjb/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>audrasjb</a> and @3kori<em> for collaboration and review.</em></p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"22114\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"Join the WordPress 7.2 Release Celebration Livestream\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:59:\"https://wordpress.org/news/2026/11/7-2-release-celebration/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 23 Nov 2026 19:06:10 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:6:\"Events\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=22101\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:343:\"On December 8, 2026, at 16:00 UTC, contributors to WordPress 7.2 will livestream the release, and you’re invited. Expect demos of what’s new and time to hear from the contributors themselves. Anyone can watch and ask questions. WordPress 7.2 will introduce Ipsum, a new default theme, and a new way to discover posts with /random [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"Nicholas Garofalo\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:2070:\"\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n<iframe title=\"WordPress 7.2 Launch Live Stream\" width=\"500\" height=\"281\" src=\"https://www.youtube.com/embed/YTq0-2dsXZQ?feature=oembed\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>\n</div></figure>\n\n\n\n<p class=\"wp-block-paragraph\">On <time class=\"wporg-time\" data-iso=\"20261208T1600\" datetime=\"2026-12-08T16:00:00-05:00\">December 8, 2026, at 16:00 UTC</time>, contributors to WordPress 7.2 will livestream the release, and you’re invited. Expect demos of what’s new and time to hear from the contributors themselves. Anyone can watch and ask questions.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 will introduce <a href=\"https://make.wordpress.org/core/2026/09/16/introducing-ipsum-the-new-default-theme/\">Ipsum</a>, a new default theme, and a new way to discover posts with /random on your site. Notes will gain emoji reactions, and the Admin dashboard will get modern, redesigned icons. Can’t wait? Every one of those features is in the <a href=\"https://wordpress.org/news/category/releases/\">latest Beta/RC release</a> today, ready for you to test.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress contributors collaborate across the globe. What they build together powers millions of sites. Come see the faces behind the commits and be a part of the latest release.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Event details</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li><strong>When:</strong> <time class=\"wporg-time\" data-iso=\"20261208T1600\" datetime=\"2026-12-08T16:00:00-05:00\">December 8, 2026 at 16:00 UTC</time></li>\n\n\n\n<li><strong>Where to watch:</strong> <a href=\"https://youtube.com/live/YTq0-2dsXZQ\">YouTube livestream</a></li>\n\n\n\n<li><strong>Questions:</strong> Join the stream chat or comment on your favorite social platform</li>\n</ul>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"22101\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:63:\"\n		\n		\n		\n		\n		\n				\n		\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:52:\"Global Partners Across the Third Quarter of the 2026\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:70:\"https://wordpress.org/news/2026/11/global-partners-third-quarter-2026/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 20 Nov 2026 17:17:24 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:3:{i:0;a:5:{s:4:\"data\";s:9:\"Community\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:6:\"Events\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:8:\"WordCamp\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=22065\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:383:\"From July through September 2026, the WordPress Community organized 39 events with the financial support of the project&#8217;s five Global Partners: Jetpack, WordPress.com, WooCommerce, Bluehost, and Hostinger. From a small gathering of 56 in Mannheim to a Contributor Day in the Philippines that drew 322 people, and the first-ever WordCamp in Eket, Nigeria, these events [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Harmony Romo\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:16511:\"\n<div class=\"wp-block-jetpack-tiled-gallery aligncenter is-style-rectangular\"><div class=\"\"><div class=\"tiled-gallery__gallery\"><div class=\"tiled-gallery__row\"><div class=\"tiled-gallery__col\" style=\"flex-basis:57.01646%\"><figure class=\"tiled-gallery__item\"><img decoding=\"async\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/11/G35LxFbWcAAWjyl-scaled-1-1024x771.jpeg?strip=info&#038;w=600&#038;ssl=1 600w,https://i0.wp.com/wordpress.org/news/files/2026/11/G35LxFbWcAAWjyl-scaled-1-1024x771.jpeg?strip=info&#038;w=900&#038;ssl=1 900w,https://i0.wp.com/wordpress.org/news/files/2026/11/G35LxFbWcAAWjyl-scaled-1-1024x771.jpeg?strip=info&#038;w=1024&#038;ssl=1 1024w\" alt=\"\" data-amp-layout=\"responsive\" data-height=\"1928\" data-id=\"22078\" data-link=\"https://wordpress.org/news/?attachment_id=22078\" data-url=\"https://wordpress.org/news/files/2026/11/G35LxFbWcAAWjyl-scaled-1-1024x771.jpeg\" data-width=\"2560\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/G35LxFbWcAAWjyl-scaled-1-1024x771.jpeg?ssl=1\"></figure></div><div class=\"tiled-gallery__col\" style=\"flex-basis:42.98354%\"><figure class=\"tiled-gallery__item\"><img decoding=\"async\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/11/Mannheim-1024x1024.jpg?strip=info&#038;w=600&#038;ssl=1 600w,https://i0.wp.com/wordpress.org/news/files/2026/11/Mannheim-1024x1024.jpg?strip=info&#038;w=900&#038;ssl=1 900w,https://i0.wp.com/wordpress.org/news/files/2026/11/Mannheim-1024x1024.jpg?strip=info&#038;w=1024&#038;ssl=1 1024w\" alt=\"\" data-amp-layout=\"responsive\" data-height=\"2560\" data-id=\"22079\" data-link=\"https://wordpress.org/news/?attachment_id=22079\" data-url=\"https://wordpress.org/news/files/2026/11/Mannheim-1024x1024.jpg\" data-width=\"2560\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/Mannheim-1024x1024.jpg?ssl=1\"></figure></div></div></div></div></div>\n\n\n\n<p class=\"wp-block-paragraph\">From July through September 2026, the WordPress Community organized 39 events with the financial support of the project&#8217;s five <a href=\"https://events.wordpress.org/sponsor/\">Global Partners</a>: Jetpack, WordPress.com, WooCommerce, Bluehost, and Hostinger. From a small gathering of 56 in Mannheim to a Contributor Day in the Philippines that drew 322 people, and the first-ever WordCamp in Eket, Nigeria, these events brought newcomers, contributors, and builders together around the world. The 39 events were too many to cover in one post, so this recap highlights a few of the moments that stood out.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Events around the world</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The quarter opened in July with <a href=\"https://mannheim.wordcamp.org/2026/\">WordCamp Mannheim</a>, a small event with real range. The 56 attendees covered topics from AI and WordPress block development to current security know-how, along with presentations on values, training, and the open web.</p>\n\n\n\n<figure class=\"wp-block-image size-full\" style=\"margin-right:0;margin-left:0\"><img data-recalc-dims=\"1\" fetchpriority=\"high\" decoding=\"async\" width=\"2048\" height=\"1365\" alt=\"\" class=\"wp-image-22097\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/Eket.jpg?resize=2048%2C1365&#038;ssl=1\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/11/Eket.jpg?w=2048&amp;ssl=1 2048w, https://i0.wp.com/wordpress.org/news/files/2026/11/Eket.jpg?resize=300%2C200&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2026/11/Eket.jpg?resize=767%2C511&amp;ssl=1 767w, https://i0.wp.com/wordpress.org/news/files/2026/11/Eket.jpg?resize=1024%2C683&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2026/11/Eket.jpg?resize=1536%2C1024&amp;ssl=1 1536w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">In August, the momentum moved to Nigeria, where <a href=\"https://eket.wordcamp.org/2026/\">Eket held its inaugural WordCamp</a> on August 15 under the theme &#8220;From Idea to Income: Building Opportunities with WordPress.&#8221; <a href=\"https://eket.wordcamp.org/2026/speaker/engr-aniebiet-udoh-fnse/\">Engr. Aniebiet Udoh</a> took the stage for the keynote, challenging attendees to embrace the global reach of the web: &#8220;The internet has no small towns.&#8221; He urged creators to follow a five-step path:</p>\n\n\n\n<ol class=\"wp-block-list\">\n<li>Notice a local pain</li>\n\n\n\n<li>Solve for one person</li>\n\n\n\n<li>Validate with real use</li>\n\n\n\n<li>Standardize the repeatable core</li>\n\n\n\n<li>Scale to global markets</li>\n</ol>\n\n\n\n<p class=\"wp-block-paragraph\">Later in August, <a href=\"https://philippines.wordcamp.org/2026/\">WordCamp Philippines</a> drew approximately 434 attendees, contributors and first-time attendees, to Iloilo City on August 28-29.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One of the highlights of Contributor Day was the Open Source Library, an activity inspired by the Human Library concept. Instead of borrowing a book, participants could &#8220;borrow&#8221; a person and spend time having a meaningful conversation about their experiences, careers, communities, and journeys in open source.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress.com ran both a booth and a dedicated Community + Education table. The education table alone generated connections with 14 schools and universities, sparked three new meetup applications, and produced a new Campus Connect application from Colegio San Agustin in Bacolod.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Students and first-timers in Uganda</h2>\n\n\n\n<p class=\"wp-block-paragraph\">In Uganda, WordPress is reaching people who have never worked with it before. The third edition of <a href=\"https://masaka.wordcamp.org/2026/\">WordCamp Masaka</a> welcomed students and first-timers to participate in a hands-on WordPress Practical session. Led by community members, <a href=\"https://profiles.wordpress.org/stephendumba1/\">Stephen Dumba</a> and Cinderella Mbabazi, <a href=\"https://www.linkedin.com/in/namyalo-florence-b87a82303/\">Florence Namyalo</a>, the Founder and CEO of RAPCIO, and the IT team of Equator University of Science and Technology, the group installed WordPress, explored the dashboard, and began building websites.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img data-recalc-dims=\"1\" decoding=\"async\" width=\"1024\" height=\"683\" alt=\"\" class=\"wp-image-22075\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/image-7489660a.jpeg?resize=1024%2C683&#038;ssl=1\" style=\"aspect-ratio:1.5012468827930174\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/11/image-7489660a.jpeg?resize=1024%2C683&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2026/11/image-7489660a.jpeg?resize=300%2C200&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2026/11/image-7489660a.jpeg?resize=768%2C512&amp;ssl=1 768w, https://i0.wp.com/wordpress.org/news/files/2026/11/image-7489660a.jpeg?resize=1536%2C1025&amp;ssl=1 1536w, https://i0.wp.com/wordpress.org/news/files/2026/11/image-7489660a.jpeg?w=2048&amp;ssl=1 2048w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">In September, nearly half of this year&#8217;s participants at <a href=\"https://jinja.wordcamp.org/2026/\">WordCamp Jinja</a> were students. One of them, fascinated by the WordPress ecosystem and its spirit of generosity and inclusivity, drew all the sponsor logos by hand so he could remember them after the event.</p>\n\n\n\n<div class=\"wp-block-jetpack-tiled-gallery aligncenter is-style-rectangular\"><div class=\"\"><div class=\"tiled-gallery__gallery\"><div class=\"tiled-gallery__row\"><div class=\"tiled-gallery__col\" style=\"flex-basis:55.29651%\"><figure class=\"tiled-gallery__item\"><img decoding=\"async\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/11/image-d5ba5422-954x1024.png?strip=info&#038;w=600&#038;ssl=1 600w,https://i0.wp.com/wordpress.org/news/files/2026/11/image-d5ba5422-954x1024.png?strip=info&#038;w=900&#038;ssl=1 900w,https://i0.wp.com/wordpress.org/news/files/2026/11/image-d5ba5422-954x1024.png?strip=info&#038;w=954&#038;ssl=1 954w\" alt=\"\" data-amp-layout=\"responsive\" data-height=\"1082\" data-id=\"22068\" data-link=\"https://wordpress.org/news/?attachment_id=22068\" data-url=\"https://wordpress.org/news/files/2026/11/image-d5ba5422-954x1024.png\" data-width=\"1008\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/image-d5ba5422-954x1024.png?ssl=1\"></figure></div><div class=\"tiled-gallery__col\" style=\"flex-basis:44.70349%\"><figure class=\"tiled-gallery__item\"><img decoding=\"async\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/11/IMG-20261119-WA0223-771x1024.jpg?strip=info&#038;w=600&#038;ssl=1 600w,https://i0.wp.com/wordpress.org/news/files/2026/11/IMG-20261119-WA0223-771x1024.jpg?strip=info&#038;w=771&#038;ssl=1 771w\" alt=\"\" data-amp-layout=\"responsive\" data-height=\"2560\" data-id=\"22080\" data-link=\"https://wordpress.org/news/?attachment_id=22080\" data-url=\"https://wordpress.org/news/files/2026/11/IMG-20261119-WA0223-771x1024.jpg\" data-width=\"1927\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/IMG-20261119-WA0223-771x1024.jpg?ssl=1\"></figure></div></div></div></div></div>\n\n\n\n<h2 class=\"wp-block-heading\">From classrooms to community</h2>\n\n\n\n<figure class=\"wp-block-image size-large\"><img data-recalc-dims=\"1\" loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"447\" alt=\"\" class=\"wp-image-22070\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/image-9d01fc70.png?resize=1024%2C447&#038;ssl=1\" style=\"aspect-ratio:2.288973384030418\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/11/image-9d01fc70.png?resize=1024%2C447&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2026/11/image-9d01fc70.png?resize=300%2C131&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2026/11/image-9d01fc70.png?resize=768%2C335&amp;ssl=1 768w, https://i0.wp.com/wordpress.org/news/files/2026/11/image-9d01fc70.png?resize=1536%2C670&amp;ssl=1 1536w, https://i0.wp.com/wordpress.org/news/files/2026/11/image-9d01fc70.png?w=1920&amp;ssl=1 1920w\" sizes=\"auto, (max-width: 1000px) 100vw, 1000px\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">In September, <a href=\"https://costarica.wordcamp.org/2026/\">WordCamp Costa Rica</a> brought together 327 people. A noteworthy highlight was the pre-event <a href=\"https://developer.wordpress.com/studio/\">WordPress Studio</a> workshop, where 25 participants each built and launched a live site on WordPress.com in a single morning.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The event also demonstrated the growing pipeline from education to community. At least 100 attendees came to WordCamp Costa Rica after first experiencing WordPress through WordPress Campus Connect events at Beenova and UCR Esparza earlier in the year.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The thread running through many of these stories is education and the increasing attendance by students who have been exposed  to WordPress through the WordPress Campus Connect event series. These events serve as a pathway for the next generation of WordPress contributors, builders, and professionals, and each stop this quarter added to that pipeline.</p>\n\n\n\n<h2 class=\"wp-block-heading\">What&#8217;s next</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The current cycle of the Global Partnership Program continues through March of 2027, with WordCamps scheduled in Guatemala, Belo Horizonte, Bandung, and beyond. WordPress Campus Connect events are expanding across Latin America, Southeast Asia, and Africa. Thank you to Jetpack, WordPress.com, WooCommerce, Bluehost, and Hostinger for making this quarter possible, and to every organizer, volunteer, speaker, and attendee who brought these events to life.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images is-style-rectangular is-layout-grid wp-container-core-gallery-is-layout-5a23bf8e wp-block-gallery-is-layout-grid\">\n<figure class=\"wp-block-image size-large\"><a href=\"https://www.bluehost.com/\"><img data-recalc-dims=\"1\" loading=\"lazy\" decoding=\"async\" width=\"600\" height=\"161\" data-id=\"22084\" alt=\"\" class=\"wp-image-22084\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/Bluehost-blue-inline-600px.png?resize=600%2C161&#038;ssl=1\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/11/Bluehost-blue-inline-600px.png?w=600&amp;ssl=1 600w, https://i0.wp.com/wordpress.org/news/files/2026/11/Bluehost-blue-inline-600px.png?resize=300%2C81&amp;ssl=1 300w\" sizes=\"auto, (max-width: 600px) 100vw, 600px\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://www.hostinger.com/\"><img data-recalc-dims=\"1\" loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"205\" data-id=\"22083\" alt=\"\" class=\"wp-image-22083\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/Hostinger-logo-primary.png?resize=1024%2C205&#038;ssl=1\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/11/Hostinger-logo-primary.png?resize=1024%2C205&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2026/11/Hostinger-logo-primary.png?resize=300%2C60&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2026/11/Hostinger-logo-primary.png?resize=768%2C154&amp;ssl=1 768w, https://i0.wp.com/wordpress.org/news/files/2026/11/Hostinger-logo-primary.png?resize=1536%2C308&amp;ssl=1 1536w, https://i0.wp.com/wordpress.org/news/files/2026/11/Hostinger-logo-primary.png?w=1920&amp;ssl=1 1920w\" sizes=\"auto, (max-width: 1000px) 100vw, 1000px\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://jetpack.com/\"><img data-recalc-dims=\"1\" loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"388\" data-id=\"22081\" alt=\"\" class=\"wp-image-22081\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/Copy-of-jetpack-logo-horizontal-color.png?resize=1024%2C388&#038;ssl=1\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/11/Copy-of-jetpack-logo-horizontal-color.png?resize=1024%2C388&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2026/11/Copy-of-jetpack-logo-horizontal-color.png?resize=300%2C114&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2026/11/Copy-of-jetpack-logo-horizontal-color.png?resize=766%2C290&amp;ssl=1 766w, https://i0.wp.com/wordpress.org/news/files/2026/11/Copy-of-jetpack-logo-horizontal-color.png?resize=1536%2C582&amp;ssl=1 1536w, https://i0.wp.com/wordpress.org/news/files/2026/11/Copy-of-jetpack-logo-horizontal-color.png?w=2046&amp;ssl=1 2046w\" sizes=\"auto, (max-width: 1000px) 100vw, 1000px\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://wordpress.com/\"><img data-recalc-dims=\"1\" loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"292\" data-id=\"22082\" alt=\"\" class=\"wp-image-22082\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/Copy-of-wordpressdotcom_lockup-black.png?resize=1024%2C292&#038;ssl=1\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/11/Copy-of-wordpressdotcom_lockup-black.png?resize=1024%2C292&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2026/11/Copy-of-wordpressdotcom_lockup-black.png?resize=300%2C86&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2026/11/Copy-of-wordpressdotcom_lockup-black.png?resize=768%2C219&amp;ssl=1 768w, https://i0.wp.com/wordpress.org/news/files/2026/11/Copy-of-wordpressdotcom_lockup-black.png?resize=1536%2C438&amp;ssl=1 1536w, https://i0.wp.com/wordpress.org/news/files/2026/11/Copy-of-wordpressdotcom_lockup-black.png?resize=2048%2C584&amp;ssl=1 2048w\" sizes=\"auto, (max-width: 1000px) 100vw, 1000px\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://woocommerce.com/\"><img data-recalc-dims=\"1\" loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"523\" data-id=\"22067\" alt=\"\" class=\"wp-image-22067\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/image-c8bae577.png?resize=1024%2C523&#038;ssl=1\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/11/image-c8bae577.png?resize=1024%2C523&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2026/11/image-c8bae577.png?resize=300%2C153&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2026/11/image-c8bae577.png?resize=768%2C392&amp;ssl=1 768w, https://i0.wp.com/wordpress.org/news/files/2026/11/image-c8bae577.png?resize=1536%2C785&amp;ssl=1 1536w, https://i0.wp.com/wordpress.org/news/files/2026/11/image-c8bae577.png?w=2048&amp;ssl=1 2048w\" sizes=\"auto, (max-width: 1000px) 100vw, 1000px\" /></a></figure>\n</figure>\n\n\n\n<p class=\"wp-block-paragraph\">To learn more about WordPress community events near you, visit <a href=\"https://events.wordpress.org/\"><strong>events.wordpress.org</strong></a>.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"22065\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:63:\"\n		\n		\n		\n		\n		\n				\n		\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"WordPress Credits Boost Translation\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:64:\"https://wordpress.org/news/2026/11/wp-credits-boost-translation/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 20 Nov 2026 13:48:10 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:3:{i:0;a:5:{s:4:\"data\";s:9:\"Community\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:9:\"Education\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:17:\"WordPress Credits\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=22026\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:418:\"Contributors to the Costa Rican Spanish locale are making WordPress more accessible to Spanish-speaking communities in Costa Rica. Students from local schools and universities have joined the Polyglots team, helping translate WordPress.org projects and review community contributions. Students from two universities and a bilingual high school in Costa Rica contributed through the WordPress Credits program, [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Isotta Peira\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:3043:\"\n<p class=\"wp-block-paragraph\">Contributors to the Costa Rican Spanish locale are making WordPress more accessible to Spanish-speaking communities in Costa Rica. Students from local schools and universities have joined the Polyglots team, helping translate WordPress.org projects and review community contributions.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Students from two universities and a bilingual high school in Costa Rica contributed through the <a href=\"https://wordpress.org/education/credits/\">WordPress Credits program</a>, which lets students earn academic credit for contributing to WordPress as part of their studies. On the Polyglots team, contributors suggest translations for WordPress Core, plugins, themes, and WordPress.org sites. Locale editors review and approve those suggestions.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Between September 2025 and November 2026, translation coverage in es_CR rose from 38% to 100% on WordPress.org, from 39% to 98% in the Plugin Directory, and from 45% to 99% in the Forums. WordPress Core reached 99%, while the queue of strings waiting for review fell from 665 to 105.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One participating school, Liceo Experimental Bilingüe José Figueres Ferrer in Cartago, was the first high school in the Americas to implement WordPress Credits through its Student Community Service program, Trabajo Comunal Estudiantil. Its students focused on Polyglots and helped advance the es_CR translations.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">WP Credits pushed me to contribute to something real, not just a class assignment. Going from not knowing what a ‘string’ was to translating hundreds of them was a great feeling, and it showed me that even a ‘small’ contribution like translation genuinely helps people who use WordPress in Spanish every day.</p>\n<cite>Lester Matarrita Rodríguez, Fidélitas, May 2026</cite></blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">The project also produced a resource for new contributors. The video “<a href=\"https://wordpress.tv/2026/10/23/como-contribuir-en-el-equipo-de-traduccion/\">Cómo contribuir en el equipo de traducción</a>” walks viewers through contributing on the WordPress translation platform, using Costa Rican Spanish as an example.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you read and write a language other than English, you can help make WordPress more useful to people in your language. Start with the <a href=\"https://make.wordpress.org/polyglots/handbook/translating/first-steps/\">first steps in the Polyglots Handbook</a> to learn how to suggest translations and take part in the review process. Then check the <a href=\"https://translate.wordpress.org/stats/\">translation stats page</a> to find projects that need work in your locale. Educators can explore the <a href=\"https://wordpress.org/education/credits/\">WordPress Credits program</a> to learn how students can contribute to WordPress as part of their studies.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"22026\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:60:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"WordPress 7.1.5 Release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:59:\"https://wordpress.org/news/2026/11/wordpress-7-1-5-release/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 18 Nov 2026 17:08:59 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:8:\"Security\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=22035\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:388:\"This security release features fixes for multiple issues. Because this is a security release, it is recommended that you update your sites immediately. You can download WordPress 7.1.5 from WordPress.org, or visit your WordPress Dashboard, click “Updates,” and then click “Update Now.” If you have sites that support automatic background updates, the update process will [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:11:\"Jeremy Felt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:7294:\"\n<p class=\"wp-block-paragraph\">This security release features fixes for multiple issues.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Because this is a security release, it is recommended that you update your sites immediately.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You can <a href=\"https://wordpress.org/download/\">download WordPress 7.1.5 from WordPress.org</a>, or visit your WordPress Dashboard, click “Updates,” and then click “Update Now.” If you have sites that support automatic background updates, the update process will begin automatically.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1.5 is a short-cycle release. The next major release will be version 7.2, currently planned for December 8, 2026.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For more information, please visit the WordPress 7.1.5 <a href=\"https://wordpress.org/documentation/wordpress-version/version-7-1-5/\">HelpHub site</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Security updates included in this release</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>A malformed regular expression that broadened JSON media type matching, fixed as a hardening measure, reported by <a href=\"https://w.org/@batmoo\">Mo Jangda</a> of the WordPress Security Team.</li>\n\n\n\n<li>A multisite privilege escalation issue letting a site Administrator take over a Super Admin account via Customizer menu previews, reported by Yuval Miller.</li>\n\n\n\n<li>A reflected XSS in the legacy media library popup, reported by <a href=\"https://www.anthropic.com/\">Anthropic</a>.</li>\n\n\n\n<li>An XSS in wp_interactivity_data_wp_context() via the store namespace, reported by <a data-id=\"w.org/@jrf/\" data-type=\"link\" href=\"https://w.org/@jrf\">Juliette Reinders Folmer</a>.</li>\n\n\n\n<li>SQL injection in WP_Meta_Query via nested relation values, reported by <a href=\"https://w.org/@yougina\">Christiaan Swiers</a>.</li>\n\n\n\n<li>Unauthenticated information disclosure exposing private taxonomy terms via the REST API search endpoint, reported by Anthropic.</li>\n\n\n\n<li>Author+ information disclosure exposing user email addresses via the REST API comments endpoint, reported by Ben Bidner of the WordPress Security Team.</li>\n\n\n\n<li>SQL injection via the front page setting in Customizer changeset previews, reported by Rudy Faile of the WordPress Security Team.</li>\n\n\n\n<li>Contributor+ XSS via scripts in oEmbed provider responses, reported by vvh1te3zz.</li>\n\n\n\n<li>Unauthenticated stored XSS via shortcode attributes in comments, reported by <a href=\"https://w.org/@rafiem\">Rafie Muhammad</a> (Awesome Motive, Inc.).</li>\n\n\n\n<li>Unauthenticated denial of service via batched XML-RPC pingbacks, reported by <a href=\"https://w.org/@giovannicintolo\">Giovanni Cintolo</a>.</li>\n\n\n\n<li>Editor+ information disclosure via post and template author assignment in the REST API, reported by Jarda Snajdr of the WordPress Security Team.</li>\n\n\n\n<li>Administrator stored XSS via Customizer previews, reported by Weston Ruter of the WordPress Security Team.</li>\n\n\n\n<li>Author+ authorization bypass via comment editing in the admin, reported by Jesse McNeil.</li>\n\n\n\n<li>Subscriber+ information disclosure via XML-RPC wp.getComments, reported by <a href=\"https://github.com/dlwodnr59\">Jaewook Lee (grze0)</a>.</li>\n\n\n\n<li>A hardening change that removes the block editor&#8217;s Imgur embed variation, whose server-side provider is already gone, reported by Zhengyu Liu, <a href=\"https://jesse-yang.com/\">Jingcheng Yang</a>, and <a href=\"https://gvzhong.github.io/\">Gavin Zhong</a>.</li>\n\n\n\n<li>Contributor+ stored XSS in the Comment Date block via its date format, reported by Weston Ruter and Jeremy Felt of the WordPress Security Team.</li>\n\n\n\n<li>Unauthenticated privilege escalation via Template Part block attributes that could lead to remote code execution, reported by <a href=\"https://w.org/@logano\">Logan Homolka</a>.</li>\n\n\n\n<li>XSS in the block editor via Openverse image metadata, reported by <a href=\"https://w.org/@kq5y\">Shu Takahashi</a> of Velcore Consulting Inc.</li>\n\n\n\n<li>Contributor+ stored XSS in the block editor via media filenames when converting a media block to a File block, reported by CryptoFox.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Thank you to these WordPress contributors</h2>\n\n\n\n<p class=\"wp-block-paragraph\">This release was led by <a href=\"https://w.org/@jeremyfelt\">Jeremy Felt</a>, <a href=\"https://w.org/@jeryj\">Jerry Jones</a>, and <a href=\"https://w.org/@jsnajdr\">Jarda Snajdr</a>. WordPress 7.1.5 would not have been possible without the contributions of the following people:</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://w.org/@jorbin\">Aaron Jorbin</a>, <a href=\"https://w.org/@adamsilverstein\">Adam Silverstein</a>, <a href=\"https://w.org/@xknown\">Alex Concha</a>, <a href=\"https://w.org/@aduth\">Andrew Duthie</a>, <a href=\"https://w.org/@andrewserong\">Andrew Serong</a>, <a href=\"https://w.org/@vortfu\">Ben Bidner</a>, <a href=\"https://w.org/@yougina\">Christiaan Swiers</a>, <a href=\"https://w.org/@villanovachile\">Daniel Rodriguez</a>, <a href=\"https://w.org/@dmsnell\">Dennis Snell</a>, <a href=\"https://w.org/@ehtis\">Ehtisham Siddiqui</a>, <a href=\"https://w.org/@mamaduka\">George Mamadashvili</a>, <a href=\"https://w.org/@giovannicintolo\">Giovanni Cintolo</a>, <a href=\"https://w.org/@gziolo\">Greg Ziółkowski</a>, <a href=\"https://w.org/@isabel_brison\">Isabel Brison</a>, <a href=\"https://w.org/@jsnajdr\">Jarda Snajdr</a>, <a href=\"https://w.org/@jeremyfelt\">Jeremy Felt</a>, <a href=\"https://w.org/@jeryj\">jeryj</a>, <a href=\"https://w.org/@buffer1024\">Jesse McNeil</a>, <a href=\"https://w.org/@johnbillion\">John Blackbourn</a>, <a href=\"https://w.org/@jonsurrell\">Jon Surrell</a>, <a href=\"https://w.org/@desrosj\">Jonathan Desrosiers</a>, <a href=\"https://w.org/@jrf\">Juliette Reinders Folmer</a>, <a href=\"https://w.org/@kirasong\">Kira Schroder</a>, <a href=\"https://w.org/@lancewillett\">Lance Willett</a>, <a href=\"https://w.org/@logano\">Logan Homolka</a>, <a href=\"https://w.org/@lucatume\">Luca Tumedei</a>, <a href=\"https://w.org/@luisherranz\">luisherranz</a>, <a href=\"https://w.org/@marcs0h\">Marc Montpas</a>, <a href=\"https://w.org/@tyxla\">Marin Atanasov</a>, <a href=\"https://w.org/@batmoo\">Mohammad Jangda</a>, <a href=\"https://w.org/@ntsekouras\">Nik Tsekouras</a>, <a href=\"https://w.org/@peterwilsoncc\">Peter Wilson</a>, <a href=\"https://w.org/@rafiem\">Rafie Muhammad</a>, <a href=\"https://w.org/@ramonopoly\">ramonopoly</a>, <a href=\"https://w.org/@rfaile313\">Rudy Faile</a>, <a href=\"https://w.org/@sergey\">Sergey Biryukov</a>, <a href=\"https://w.org/@kq5y\">Shu Takahashi</a>, <a href=\"https://w.org/@westonruter\">Weston Ruter</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">Backports</h2>\n\n\n\n<p class=\"wp-block-paragraph\">As a courtesy, the security fixes were backported to all branches eligible to receive security fixes (currently through 4.7). As a reminder, only the most recent version of WordPress is actively supported. The backports are in progress and will ship as they become ready.</p>\n\n\n\n<p class=\"wp-block-paragraph\">In WordPress 7.0, 1024 bit certificates were removed from bundled root certificates. This change has been applied to 6.9.12 and earlier as part of this release.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 RC 2 has also been released, containing all applicable fixes.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"22035\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:69:\"\n		\n		\n		\n		\n		\n				\n		\n		\n		\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"WordPress 7.2 Release Candidate 1\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:69:\"https://wordpress.org/news/2026/11/wordpress-7-2-release-candidate-1/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 17 Nov 2026 16:04:13 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:5:{i:0;a:5:{s:4:\"data\";s:7:\"General\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:3:\"7.2\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:3;a:5:{s:4:\"data\";s:11:\"development\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:4;a:5:{s:4:\"data\";s:7:\"release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=22019\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:364:\"The first Release Candidate (“RC1”) for WordPress 7.2 is ready for download and testing! This version of the WordPress software is still under development. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, it’s recommended to evaluate RC1 on a test server and site. WordPress 7.2 RC1 [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"David Baumwald\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:10144:\"\n<p class=\"wp-block-paragraph\">The first Release Candidate (“RC1”) for WordPress 7.2 is ready for download and testing!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>This version of the WordPress software is still under development</strong>. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, it’s recommended to evaluate RC1 on a test server and site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 RC1 can be tested using any of the following methods:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>Plugin</strong></td><td>Install and activate the <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\" rel=\"noopener\" target=\"_blank\">WordPress Beta Tester</a> plugin on a WordPress install. (Select the “Bleeding edge” channel and “Beta/RC Only” stream.)</td></tr><tr><td><strong>Direct Download</strong></td><td>Download the <a href=\"https://wordpress.org/wordpress-7.2-RC1.zip\">RC1 version (zip)</a> and install it on a WordPress website.</td></tr><tr><td><strong>Command Line</strong></td><td>Use this <a href=\"https://make.wordpress.org/cli/\">WP-CLI</a> command: <br><code>wp core update --version=7.2-RC1</code></td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use the <a href=\"http://playground.wordpress.net/release\" rel=\"noopener\" target=\"_blank\">WordPress Playground instance</a> to test the software directly in your browser.  No setup required – just click and go!</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The scheduled final release date for WordPress 7.2 is <strong>December 8, 2026</strong>. The full <a href=\"https://make.wordpress.org/core/2026/10/06/wordpress-7-2-release-party-schedule/\" rel=\"noopener\" target=\"_blank\">release schedule can be found here</a>. Your help testing Beta and RC versions is vital to making this release as stable and powerful as possible. Thank you to everyone who contributes by testing!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Please continue checking the <a href=\"https://make.wordpress.org/core/\" rel=\"noopener\" target=\"_blank\">Make WordPress Core blog</a> for <a href=\"https://make.wordpress.org/core/tag/7-2\" rel=\"noopener\" target=\"_blank\">7.2-related posts</a> in the coming weeks for more information.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Core Changes Since Beta 5</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Check out the <a href=\"https://wordpress.org/news/2026/10/wordpress-7-2-beta-1-is-ready-for-download-and-testing/\">Beta 1 announcement</a> for details on WordPress 7.2.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You can browse the technical details for all issues addressed since Beta 5 using these links:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://core.trac.wordpress.org/query?changetime=11%2F10%2F2026..11%2F17%2F2026&amp;milestone=7.2&amp;status=closed&amp;group=component&amp;order=id&amp;col=id&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority\">Closed 7.2 WordPress Core Trac tickets</a> since November 10, 2026</li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/commits/wp/7.2?since=2026-11-10&amp;until=2026-11-17\">7.2 Gutenberg commits</a> since November 10, 2026</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 Release Candidate 1 brings additional bug fixes, accessibility improvements, and compatibility updates as the release moves closer to its December 8 launch.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Recent refinements include fixes to client-side media uploads, improvements to the new random-content redirect feature, and better keyboard navigation through a skip link in the WordPress admin bar. Additional updates improve plugin dependency messaging, script module translations, and the reliability of the HTML and Interactivity APIs.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Developers will also benefit from continued Abilities API refinements and updates to bundled libraries, including PHPMailer, Requests, getID3, and sodium_compat.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/66490\">Trac #66490</a>, <a href=\"https://core.trac.wordpress.org/ticket/66681\">Trac #66681</a>, <a href=\"https://core.trac.wordpress.org/ticket/66625\">Trac #66625</a>, <a href=\"https://core.trac.wordpress.org/ticket/66331\">Trac #66331</a>, <a href=\"https://core.trac.wordpress.org/ticket/66591\">Trac #66591</a>, <a href=\"https://core.trac.wordpress.org/ticket/65984\">Trac #65984</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Additional Block Editor Improvements</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 RC1 includes further refinements to the block editor, addressing issues with duplicated block content, keyboard interactions on iOS, and revision previews. Improvements to the Interactivity API prevent outdated navigation responses from replacing newer content, while additional fixes improve plugin installation workflows, featured image compatibility, and link suggestions. The transition to modern SVG icons also continues throughout WordPress administration.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/pull/86839\">GitHub #86839</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/86703\">GitHub #86703</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/86608\">GitHub #86608</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/78367\">GitHub #78367</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/86854\">GitHub #86854</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">Want to know more about this release? Here are some highlights:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>New Ipsum default theme</li>\n\n\n\n<li>Expanded responsive design and Gallery controls</li>\n\n\n\n<li>Improved Global Styles and typography tools</li>\n\n\n\n<li>Enhanced Canvas Notes and collaboration</li>\n\n\n\n<li>New DataForm block settings inspector</li>\n\n\n\n<li>Faster media uploads and image processing</li>\n\n\n\n<li>Modernized WordPress admin with SVG icons</li>\n\n\n\n<li>Faster admin navigation and asset loading</li>\n\n\n\n<li>New “On This Day” widget and random post discovery</li>\n\n\n\n<li>Improved translation update management</li>\n\n\n\n<li>Accessibility, security, and PHP 8.6 compatibility improvements</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">How you can contribute</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress is open source software made possible by a passionate community of people collaborating on and contributing to its development. The resources below outline various ways you can help the world’s most popular open source web platform, regardless of your technical expertise.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Get involved in testing</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Testing for issues is crucial to the development of any software. It’s also a meaningful way for anyone to contribute. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Your help testing the WordPress 7.2 RC1 version is key to ensuring that the final release is the best it can be. While testing the upgrade process is essential, trying out new features is equally important. This <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\" rel=\"noopener\" target=\"_blank\">detailed guide</a> will walk you through testing features in WordPress 7.2.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Update your theme or plugin</h3>\n\n\n\n<p class=\"wp-block-paragraph\">For plugin and theme authors, your products play an integral role in extending the functionality and value of WordPress for all users.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Thanks for continuing to test your themes and plugins with the WordPress 7.2 beta releases. With RC1, you’ll want to conclude your testing and update the <em>“Tested up to”</em> version in your <a href=\"https://developer.wordpress.org/plugins/wordpress-org/how-your-readme-txt-works/\" rel=\"noopener\" target=\"_blank\">plugin’s readme file</a> to 7.2.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you find compatibility issues, please post detailed information to the <a href=\"https://wordpress.org/support/forum/alphabeta/\" rel=\"noopener\" target=\"_blank\">support forum</a>.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Test on your hosting platforms</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Web hosts provide vital infrastructure for supporting WordPress and its users. Testing on hosting systems helps inform the development process while ensuring that WordPress and hosting platforms are fully compatible, free of errors, optimized for the best possible user experience, and that updates roll out to customer sites without issue.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Want to test WordPress on your hosting system? <a href=\"https://make.wordpress.org/hosting/test-results-getting-started/\" rel=\"noopener\" target=\"_blank\">Get started with configuring distributed hosting tests here</a>. Thank you to all <a href=\"https://make.wordpress.org/hosting/test-results/\" rel=\"noopener\" target=\"_blank\">web hosts who help test WordPress</a>!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Curious about testing releases in general? Follow along with the <a href=\"https://make.wordpress.org/test/\" rel=\"noopener\" target=\"_blank\">testing initiatives in Make Core</a> and join the <a href=\"https://wordpress.slack.com/messages/core-test/\" rel=\"noopener\" target=\"_blank\">#core-test channel</a> on <a href=\"https://wordpress.slack.com/\" rel=\"noopener\" target=\"_blank\">Making WordPress Slack</a>.</p>\n\n\n\n<h3 class=\"wp-block-heading\">An RC1 haiku</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><em>The final bugs fall</em><br><em>Release candidate takes flight</em><br><em>Launch day draws nearer</em></p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Props to <a href=\'https://profiles.wordpress.org/audrasjb/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>audrasjb</a>, <a href=\'https://profiles.wordpress.org/r1k0/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>r1k0</a>, and <a href=\'https://profiles.wordpress.org/courane01/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>courane01</a> for collaboration and review.</em></p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"22019\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:58:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:37:\"Copy Your WordPress Site with Reprint\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"https://wordpress.org/news/2026/11/reprint-your-site/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 13 Nov 2026 12:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:11:\"Development\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=22001\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:359:\"Reprint is a free, open-source, PHP-based tool that copies a WordPress site’s files and database. The plugin is available in the WordPress.org Plugin Directory, along with the command-line client used to copy the site. WordPress has long let you export your posts and pages. Moving the site itself means bringing along its theme, plugins, uploads, [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:9:\"enclosure\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:3:{s:3:\"url\";s:52:\"https://videos.files.wordpress.com/KvhaIGjZ/pull.mp4\";s:6:\"length\";s:6:\"625628\";s:4:\"type\";s:9:\"video/mp4\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"Adam Zieliński\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:5688:\"\n<p class=\"wp-block-paragraph\">Reprint is a free, open-source, PHP-based tool that copies a WordPress site’s files and database. The plugin is available in the <a href=\"https://wordpress.org/plugins/reprint/\">WordPress.org Plugin Directory</a>, along with the command-line client used to copy the site.</p>\n\n\n<figure class=\"wp-block-post-featured-image\"><img data-recalc-dims=\"1\" loading=\"lazy\" decoding=\"async\" width=\"2560\" height=\"1440\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/reprint-hero-scaled.png?resize=2560%2C1440&#038;ssl=1\" class=\"attachment-post-thumbnail size-post-thumbnail wp-post-image\" alt=\"\" style=\"object-fit:cover;\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/11/reprint-hero-scaled.png?w=2560&amp;ssl=1 2560w, https://i0.wp.com/wordpress.org/news/files/2026/11/reprint-hero-scaled.png?resize=300%2C169&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2026/11/reprint-hero-scaled.png?resize=1024%2C576&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2026/11/reprint-hero-scaled.png?resize=768%2C432&amp;ssl=1 768w, https://i0.wp.com/wordpress.org/news/files/2026/11/reprint-hero-scaled.png?resize=1536%2C864&amp;ssl=1 1536w, https://i0.wp.com/wordpress.org/news/files/2026/11/reprint-hero-scaled.png?resize=2048%2C1152&amp;ssl=1 2048w\" sizes=\"auto, (max-width: 1000px) 100vw, 1000px\" /></figure>\n\n\n<p class=\"wp-block-paragraph\">WordPress has long let you <a href=\"https://wordpress.org/documentation/article/tools-export-screen/\">export your posts and pages</a>. Moving the site itself means bringing along its theme, plugins, uploads, and settings, too. Making that easier has been part of <a href=\"https://make.wordpress.org/core/2024/06/21/data-liberation-and-wordpress-migrations/\">WordPress’s Data Liberation work</a> since 2024.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Example use cases</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You can use Reprint to copy your site to a new host, or to create a local copy meant for testing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">While moving your site to a new host, visitors can keep using the original. Use Reprint to copy the site, and then open the copy to check that your pages load, your images appear, and your forms work before you send visitors there. When you’re ready to switch, pause changes on the original site, make one last copy, and point your domain to the new host. The <a href=\"https://developer.wordpress.org/reprint/guides/move-to-another-host/\">step-by-step guide to moving your site</a> walks you through the move.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You can also use Reprint to create a site copy meant for testing, a place to try changes without affecting the site your visitors use. <a href=\"https://developer.wordpress.org/reprint/getting-started/copy-a-site/\">Copy your site to your computer</a> or try the <a href=\"https://playground.wordpress.net/?clone-site=https%3A%2F%2Freprint-demo.wordpress.net\">experimental, browser-based option in WordPress Playground</a>. Use the copy to try a new layout with your existing pages, see how a plugin fits into your site, or check that everything still works after a WordPress update.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How Reprint copies a site</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Reprint sends your files and database directly to the computer or server you choose, one piece at a time, without needing to connect to an external service. The transfer can begin without your old host having to make room for an archive of the whole site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If the connection drops during the copy, you can resume from the last saved point. If you give Reprint a new site address, it can update links that point to the old one. It builds on the <a href=\"https://make.wordpress.org/core/2025/11/27/wordpress-importer-can-now-migrate-urls-in-your-content/\">WordPress Importer’s approach to rewriting links</a> and applies it to the copied database, including links stored in site settings, blocks, shortcodes, and complex data structures like serialized data or custom fields safely without corrupting tables.</p>\n\n\n\n		<figure class=\"wp-block-jetpack-videopress jetpack-videopress-player\" style=\"\" >\n			<div class=\"jetpack-videopress-player__wrapper\"> <iframe loading=\"lazy\" title=\"VideoPress Video Player\" aria-label=\"VideoPress Video Player\" width=\"500\" height=\"293\" src=\"https://videopress.com/embed/KvhaIGjZ?cover=1&amp;autoPlay=1&amp;controls=0&amp;loop=1&amp;muted=1&amp;persistVolume=0&amp;playsinline=1&amp;preloadContent=metadata&amp;useAverageColor=1&amp;hd=0\" frameborder=\"0\" allowfullscreen data-resize-to-parent=\"true\" allow=\"clipboard-write; presentation\"></iframe><script src=\'https://v0.wordpress.com/js/next/videopress-iframe.js?m=1790791280\'></script></div>\n			\n			\n		</figure>\n		\n\n\n<p class=\"wp-block-paragraph\">When copying a site repeatedly, Reprint figures out what changed since the last time and copies only the files it needs.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Try Reprint</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You don’t need to connect your own site to see how Reprint works. Try the <a href=\"https://playground.wordpress.net/?clone-site=https%3A%2F%2Freprint-demo.wordpress.net\">experimental, browser-based option in WordPress Playground</a>. You can copy a sample site right in your browser, with nothing to install.</p>\n\n\n\n<p class=\"wp-block-paragraph\">When you’re ready to work with your own pages and settings, start with a test site you manage. The <a href=\"https://developer.wordpress.org/reprint/getting-started/copy-a-site/\">guide to making your first copy</a> takes you from installing the plugin to opening the copied site on your computer.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"22001\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:60:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:38:\"WordCamp Asia 2027 Is Coming to Penang\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"https://wordpress.org/news/2026/11/wc-asia-2027-penang/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 11 Nov 2026 14:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:9:\"Community\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:6:\"Events\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21919\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:344:\"Next year, WordCamp Asia 2027 heads to Penang, Malaysia. From April 9 to 11, the WordPress community will gather at the Penang Waterfront Convention Centre for three days of contribution, learning, and connection. Tickets are on sale and sponsorship applications are open, so now is the time to make your plans. In 2026, WordCamp Asia [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"Nicholas Garofalo\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:81545:\"\n<p class=\"wp-block-paragraph\">Next year, WordCamp Asia 2027 heads to Penang, Malaysia. From April 9 to 11, the WordPress community will gather at the Penang Waterfront Convention Centre for three days of contribution, learning, and connection. Tickets are on sale and sponsorship applications are open, so now is the time to make your plans.</p>\n\n\n\n<div class=\"wp-block-buttons is-content-justification-center is-layout-flex wp-container-core-buttons-is-layout-82d461e8 wp-block-buttons-is-layout-flex\">\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-background wp-element-button\" href=\"https://asia.wordcamp.org/2027/tickets/\" rel=\"noreferrer noopener\" style=\"background:linear-gradient(135deg,rgb(42,5,123) 0%,rgb(42,5,123) 100%)\" target=\"_blank\">Get Your Event Pass</a></div>\n\n\n\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-background wp-element-button\" href=\"https://asia.wordcamp.org/2027/call-for-sponsors/\" rel=\"noreferrer noopener\" style=\"background:linear-gradient(135deg,rgb(42,5,123) 0%,rgb(42,5,123) 100%)\" target=\"_blank\">Become a Sponsor</a></div>\n\n\n\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-background wp-element-button\" href=\"https://asia.wordcamp.org/2027/\" rel=\"noreferrer noopener\" style=\"background:linear-gradient(135deg,rgb(42,5,123) 0%,rgb(42,5,123) 100%)\" target=\"_blank\">About WordCamp Asia</a></div>\n</div>\n\n\n\n<p class=\"wp-block-paragraph\">In 2026, <a href=\"https://wordpress.org/news/2026/04/celebrating-wcasia-2026/\">WordCamp Asia</a> brought 2,627 attendees to Mumbai, India. More than 1,500 participants joined Contributor Day, where table leads guided work on more than 20 contribution tables. The conference days that followed covered topics ranging from AI and developer workflows to enterprise WordPress and journalism on the open web, and closed with a panel featuring WordPress Executive Director <a href=\"https://profiles.wordpress.org/4thhubbard/\">Mary Hubbard</a>, <a href=\"https://profiles.wordpress.org/peterwilsoncc/\">Peter Wilson</a>, and <a href=\"https://profiles.wordpress.org/sergeybiryukov/\">Sergey Biryukov</a>.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">WordPress is not a company. It is a shared commitment to keeping the web open.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Mary Hubbard, Executive Director, WordPress</em></p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">The mix of hands-on work and big-picture conversation is what sets a WordCamp apart. You learn from the people who build, scale, and maintain WordPress every day, trade ideas in the hallway between sessions, and head home with new collaborators and fresh energy for the work ahead.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Penang offers a memorable setting for WC Asia. George Town, a short drive from the venue, is a UNESCO World Heritage Site, and National Geographic named Penang one of the best places in the world to travel to in 2027. The island is famous for its food, from internationally-recognized street food to fine dining, and it is one of Malaysia’s leading destinations for tourism. If you can, give yourself a day or two on either side of the conference to explore.</p>\n\n\n\n<figure data-wp-context=\"{&quot;galleryId&quot;:&quot;6b0648d2b30aa&quot;}\" data-wp-interactive=\"core/gallery\" class=\"wp-block-gallery alignfull has-nested-images columns-8 is-cropped has-black-background-color has-background wp-block-gallery-1 is-layout-flex wp-container-core-gallery-is-layout-db4b8a9e wp-block-gallery-is-layout-flex\" style=\"border-width:20px;border-radius:2px\">\n<figure data-wp-context=\"{&quot;imageId&quot;:&quot;6b0648d2b3638&quot;}\" data-wp-interactive=\"core/image\" data-wp-key=\"6b0648d2b3638\" class=\"wp-block-image size-large wp-lightbox-container\"><img data-recalc-dims=\"1\" loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"684\" data-wp-class--hide=\"state.isContentHidden\" data-wp-class--show=\"state.isContentVisible\" data-wp-init=\"callbacks.setButtonStyles\" data-wp-on--click=\"actions.showLightbox\" data-wp-on--load=\"callbacks.setButtonStyles\" data-wp-on--pointerdown=\"actions.preloadImage\" data-wp-on--pointerenter=\"actions.preloadImageWithDelay\" data-wp-on--pointerleave=\"actions.cancelPreload\" data-wp-on-window--resize=\"callbacks.setButtonStyles\" data-id=\"21983\" alt=\"\" class=\"wp-image-21983\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/34544681862_e804672e3e_k.jpg?resize=1024%2C684&#038;ssl=1\" srcset=\"https://i0.wp.com/wordpress.org/news/files/2026/11/34544681862_e804672e3e_k.jpg?resize=1024%2C684&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2026/11/